    {id:"c3",year:"2024/2025",fieldId:"a",crop:"Feijão",area:18,yield:34.2,plantingDate:"2024-11-10",harvestDate:"2025-03-15",cost:0,inputs:"Demonstração",problems:"",notes:"Registo de demonstração."},
    {id:"c4",year:"2025/2026",fieldId:"a",crop:"Milho",area:18,yield:73.8,plantingDate:"2025-11-15",harvestDate:"2026-04-22",cost:0,inputs:"Demonstração",problems:"",notes:"Registo de demonstração."}
