let state = loadState(), maps = {}, selectedFieldId=null, climateChart=null, weatherData=null, monitoringFieldId=null, lastNdviResult=null, soilMoistureChart=null, lastNdviComparison=null;
function loadState(){try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY));if(v&&v.fields&&v.campaigns){v.settings={...initialState.settings,...(v.settings||{})};v.fields=v.fields.map(f=>({soilType:"unknown",ph:"",drainage:"Não avaliada",waterSource:"Não registada",pestHistory:"Não registado",fertilizer:"Não registado",observations:[],...f}));v.campaigns=v.campaigns.map(c=>({plantingDate:"",harvestDate:"",cost:0,inputs:"",problems:"",...c}));return v}}catch(e){}return structuredClone(initialState)}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderAll()}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2600)}
function cropClass(c){return c==="Milho"?"maize":c==="Feijão"?"beans":c==="Soja"?"soy":"empty"}
function cropIcon(c){return c==="Milho"?"♧":c==="Feijão"?"❋":c==="Soja"?"♣":"✳"}
function fieldById(id){return state.fields.find(f=>f.id===id)}
function campaignFieldName(c){return fieldById(c.fieldId)?.name||"Talhão removido"}
function totalArea(){return state.fields.reduce((a,f)=>a+Number(f.area||0),0)}
function pageName(p){return ({overview:"Visão geral",map:"Mapa inteligente",fields:"Os meus talhões",monitoring:"Monitorização",simulator:"Simulador de culturas",campaigns:"Campanhas agrícolas",assistant:"Assistente agrícola",reports:"Relatórios",settings:"Definições"})[p]||"Visão geral"}
function goPage(name){$$(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+name));$$(".nav-item[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===name));$("#crumbCurrent").textContent=pageName(name);$("#sidebar").classList.remove("open");if(name==="map"){setTimeout(()=>{initMap("mainMap");maps.mainMap?.invalidateSize();},80)}if(name==="overview"){setTimeout(()=>{initMap("overviewMap");maps.overview?.invalidateSize()},80)}if(name==="monitoring"){setTimeout(()=>{initSatellitePreview();loadClimateChart();if(monitoringFieldId)fetchPower(monitoringFieldId);renderLatestObservation()},80)}if(name==="simulator")setTimeout(updateSimulatorContext,50)}
$$("[data-page]").forEach(b=>b.addEventListener("click",()=>goPage(b.dataset.page)));
$("#mobileMenu").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
$("#closeBanner").addEventListener("click",()=>$(".demo-banner").remove());
$("#todayLabel").textContent=new Intl.DateTimeFormat("pt-PT",{dateStyle:"medium"}).format(new Date());
function renderStats(){$("#statArea").innerHTML=`${totalArea().toFixed(1)} <small>ha</small>`;$("#statFields").textContent=state.fields.length;$("#statCampaigns").textContent=state.campaigns.length;$("#statCrops").textContent=new Set(state.fields.map(f=>f.crop).filter(c=>c!=="Em preparação")).size;$("#campaignTotal").textContent=state.campaigns.length;const prod=state.campaigns.reduce((a,c)=>a+Number(c.yield||0),0);$("#productionTotal").innerHTML=`${prod.toFixed(1)} <small>t</small>`;$("#lastCampaign").textContent=state.campaigns.map(c=>c.year).sort().at(-1)||"—"}
function renderOverviewFields(){$("#overviewFieldList").innerHTML=state.fields.slice(0,5).map(f=>`<div class="field-list-item" data-open-field="${f.id}"><div class="field-color">${cropIcon(f.crop)}</div><div><b>${esc(f.name)}</b><small>${esc(f.crop)} · ${esc(f.soil||"Solo não caracterizado")}</small></div><span class="field-area">${Number(f.area).toLocaleString("pt-PT")} ha</span></div>`).join("")||'<p class="small-note">Ainda não existem talhões.</p>'}
function renderFields(){const q=($("#fieldSearch")?.value||"").toLowerCase();const list=state.fields.filter(f=>(f.name+" "+f.crop).toLowerCase().includes(q));$("#fieldCount").textContent=`${list.length} talhões`;$("#fieldCards").innerHTML=list.map(f=>`<article class="field-card" data-edit-field="${f.id}"><div class="field-card-top"><div class="field-card-icon">${cropIcon(f.crop)}</div><span class="pill ${f.crop==="Em preparação"?"empty":""}">${esc(f.crop)}</span></div><h3>${esc(f.name)}</h3><p>${esc(f.soil||"Solo não caracterizado")}</p><div class="field-card-stats"><span>Área</span><b>${Number(f.area).toLocaleString("pt-PT")} ha</b></div><div class="field-card-stats"><span>Cultura anterior</span><b>${esc(f.previous||"Não registada")}</b></div></article>`).join("")||'<div class="panel">Nenhum talhão encontrado.</div>'}
function renderCampaigns(){const tbody=$("#campaignTable");tbody.innerHTML=state.campaigns.map(c=>`<tr><td><b>${esc(c.year)}</b><small class="table-sub">${esc(c.plantingDate||"Plantação não indicada")} ${c.harvestDate?"→ "+esc(c.harvestDate):""}</small></td><td>${esc(campaignFieldName(c))}</td><td>${esc(c.crop)}</td><td>${Number(c.area).toLocaleString("pt-PT")} ha</td><td>${c.yield?Number(c.yield).toFixed(2)+" t":"—"}</td><td>${c.cost?Number(c.cost).toLocaleString("pt-PT")+" Kz":"—"}</td><td>${esc(c.problems||c.notes||"—")}</td><td><button class="table-action" data-delete-campaign="${c.id}" title="Apagar">×</button></td></tr>`).join("")||'<tr><td colspan="8">Ainda não existem campanhas registadas.</td></tr>'}
function renderReports(){const counts={};state.fields.forEach(f=>counts[f.crop]=(counts[f.crop]||0)+1);const max=Math.max(1,...Object.values(counts));$("#cropDistribution").innerHTML=Object.entries(counts).map(([k,v])=>`<div class="distribution-row"><span>${esc(k)}</span><div class="distribution-track"><div class="distribution-fill" style="width:${v/max*100}%"></div></div><b>${v}</b></div>`).join("")||"Sem registos";$("#reportSummary").innerHTML=`<div><span>Área total</span><b>${totalArea().toFixed(1)} ha</b></div><div><span>Número de talhões</span><b>${state.fields.length}</b></div><div><span>Campanhas</span><b>${state.campaigns.length}</b></div><div><span>Produção registada</span><b>${state.campaigns.reduce((a,c)=>a+Number(c.yield||0),0).toFixed(2)} t</b></div><div><span>Armazenamento</span><b>LocalStorage</b></div>`}
function renderSelects(){const opts=state.fields.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join("");$("#simField").innerHTML=opts;$("#campaignField").innerHTML=opts;const mon=$("#monitorFieldSelect");if(mon){const old=monitoringFieldId||mon.value;mon.innerHTML=opts;monitoringFieldId=state.fields.some(f=>f.id===old)?old:(state.fields[0]?.id||null);mon.value=monitoringFieldId||"";}}
const pageGuides={
 map:{title:"Mapa inteligente",text:"Este mapa mostra onde ficam os talhões. Pode alternar entre mapa de ruas e imagem de satélite, seleccionar uma parcela ou desenhar os seus limites.",steps:"Para desenhar: escolha Novo talhão, clique nos cantos da parcela (pelo menos 3 pontos), conclua o desenho e guarde o formulário. A área é calculada a partir do polígono.",tip:"A imagem de satélite é uma referência cartográfica, não uma transmissão ao vivo. Confirme sempre os limites reais no terreno."},
 fields:{title:"Os meus talhões",text:"Cada talhão representa uma parcela física da exploração e guarda a sua área, cultura actual, solo, água, observações e histórico.",steps:"Use Adicionar talhão para criar uma parcela. Clique num cartão para abrir o passaporte, consultar os dados ou editar. Preencha apenas o que conhece; não invente valores.",tip:"Quanto mais completos forem os dados de solo, água e cultura anterior, mais útil será a análise e a comparação de campanhas."},
 monitoring:{title:"Monitorização",text:"Aqui consulta dados meteorológicos regionais, observações feitas no terreno e imagens/índices de satélite disponíveis para o talhão seleccionado.",steps:"Seleccione o talhão, escolha a data e actualize os dados. Para NDVI científico, desenhe primeiro o limite do talhão e execute o cálculo Sentinel-2. Registe também observações presenciais.",tip:"NDVI é um indicador da resposta da vegetação, não confirma sozinho doença, praga ou falta de água. SMAP/NASA POWER são estimativas em grelha regional, não sensores instalados no talhão."},
 simulator:{title:"Simulador de culturas",text:"Compara cenários de rotação com base na cultura anterior, perfil de solo, água e campanhas registadas.",steps:"Escolha um talhão, confirme os dados de solo e água, marque as estratégias e carregue em Comparar estratégias.",tip:"Os resultados são cenários educativos com regras gerais. Não são previsão de produção nem substituem aconselhamento agronómico local."},
 campaigns:{title:"Campanhas agrícolas",text:"Uma campanha é um ciclo de produção: o que foi plantado, quando, em que área, quanto foi colhido e que custos ou problemas ocorreram.",steps:"Carregue em Registar campanha, escolha o talhão, indique cultura e período e preencha produção/custos quando existirem dados reais.",tip:"Registos consistentes permitem comparar resultados entre anos. Não confunda valores estimados com produção efectivamente pesada."},
 assistant:{title:"Assistente agrícola",text:"Faça perguntas sobre os dados que já estão guardados no navegador, como áreas, culturas, campanhas e clima consultado.",steps:"Escolha uma pergunta sugerida ou escreva uma pergunta curta e específica. Indique o nome do talhão quando quiser uma resposta sobre uma parcela.",tip:"Nesta versão o assistente usa respostas locais predefinidas; não é um agrónomo, não consulta toda a Internet e não está ligado a um modelo externo."},
 reports:{title:"Relatórios",text:"Esta área resume os registos inseridos: distribuição das culturas, área, campanhas e produção declarada.",steps:"Leia os totais e confirme se os registos estão completos. Use Exportar dados JSON para guardar uma cópia de segurança dos dados locais.",tip:"Os relatórios só são tão fiáveis quanto os dados introduzidos. Campos vazios não significam produção zero."},
 settings:{title:"Definições",text:"Configure a identificação e a localização da exploração e consulte como os dados são guardados e de onde vêm as camadas ambientais.",steps:"Confirme nome, latitude, longitude e região. Guarde a configuração. Antes de restaurar a demonstração ou limpar o navegador, exporte os seus dados.",tip:"Os registos ficam neste navegador e computador (LocalStorage). Não existe sincronização automática entre dispositivos nesta versão."}
};
function renderPageGuides(){Object.entries(pageGuides).forEach(([key,g])=>{const page=document.querySelector(`#page-${key}`);if(!page||page.querySelector('.page-guide'))return;const guide=document.createElement('aside');guide.className='page-guide';guide.innerHTML=`<div class="page-guide-icon">i</div><div><b>${g.title}: como utilizar</b><p>${g.text}</p><p><strong>Como fazer:</strong> ${g.steps}</p><p class="guide-tip"><strong>Importante:</strong> ${g.tip}</p></div>`;const heading=page.querySelector('.page-heading');if(heading)heading.insertAdjacentElement('afterend',guide);else page.prepend(guide)})}
function renderFarmReading(){const fields=state.fields||[], campaigns=state.campaigns||[];const noSoil=fields.filter(f=>!f.soilType||f.soilType==='unknown').length;const noWater=fields.filter(f=>!f.waterSource||f.waterSource==='Não registada').length;const noObs=fields.filter(f=>!(f.observations||[]).length).length;const complete=fields.length>0&&noSoil===0&&noWater===0&&noObs===0;const latest=fields.flatMap(f=>(f.observations||[]).map(o=>({...o,field:f.name}))).sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];
 const pill=$('#farmStatusPill');pill.textContent=fields.length===0?'Sem talhões':complete?'Registos completos':'Há dados por completar';pill.className='farm-status-pill '+(complete?'is-good':fields.length?'is-attention':'is-empty');
 $('#farmStatusTitle').textContent=fields.length===0?'Ainda não há talhões registados':complete?'A exploração tem uma boa base de registos':'A exploração ainda precisa de alguns registos';
 $('#farmStatusText').textContent=fields.length===0?'Comece por adicionar a primeira parcela. Sem talhões não é possível organizar a monitorização.':`${fields.length} talhões e ${campaigns.length} campanhas estão guardados neste navegador. ${latest?`A observação mais recente registada é de ${latest.field} (${latest.date}).`:'Ainda não existem observações de campo associadas aos talhões.'}`;
 $('#farmKnown').textContent=`${totalArea().toLocaleString('pt-PT',{maximumFractionDigits:1})} ha em ${fields.length} talhões; ${campaigns.length} campanhas registadas.`;
 $('#farmMissing').textContent=fields.length?`${noSoil} talhão(ões) sem perfil de solo; ${noWater} sem fonte de água; ${noObs} sem observação de campo.`:'Adicione um talhão e registe a área e a cultura.';
 $('#farmNext').textContent=fields.length===0?'Criar o primeiro talhão':noSoil||noWater? 'Completar solo e disponibilidade de água nos talhões':noObs?'Registar uma observação presencial':'Consultar a monitorização e comparar datas';
}
function renderAll(){renderStats();renderOverviewFields();renderFields();renderCampaigns();renderReports();renderSelects();renderFarmReading();renderPageGuides();if(maps.mainMap||maps.overview)refreshMapLayers()}
$("#fieldSearch").addEventListener("input",renderFields);
document.addEventListener("click",e=>{const card=e.target.closest("[data-edit-field]");if(card)openPassportDialog(card.dataset.editField);const quick=e.target.closest("[data-open-field]");if(quick){goPage("map");setTimeout(()=>selectField(quick.dataset.openField),180)}const del=e.target.closest("[data-delete-campaign]");if(del&&confirm("Apagar este registo de campanha?")){state.campaigns=state.campaigns.filter(c=>c.id!==del.dataset.deleteCampaign);saveState();toast("Campanha removida.")}});
function openFieldDialog(id=null){const f=id?fieldById(id):null;$("#fieldDialogTitle").textContent=f?"Editar talhão":"Adicionar talhão";$("#fieldId").value=f?.id||"";$("#fieldName").value=f?.name||`Talhão ${String.fromCharCode(65+state.fields.length)}`;$("#fieldArea").value=f?.area||"";$("#fieldCrop").value=f?.crop||"Milho";$("#fieldSoil").value=f?.soil||"";$("#fieldSoilType").value=f?.soilType||"unknown";$("#fieldPH").value=f?.ph||"";$("#fieldDrainage").value=f?.drainage||"Não avaliada";$("#fieldWater").value=f?.waterSource||"Não registada";$("#fieldPests").value=f?.pestHistory||"";$("#fieldFertilizer").value=f?.fertilizer||"";$("#fieldNotes").value=f?.notes||"";$("#fieldDate").value=f?.date||"";$("#fieldDialog").showModal()}
