$("#fieldDialog").addEventListener("close",()=>{const m=maps.mainMap;if(m?._drawPolygon){m.removeLayer(m._drawPolygon);m._drawPolygon=null;}if(m){m._pendingBoundary=null;m._pendingArea=null;}$("#fieldAreaHelp").textContent="Introduza a área ou desenhe o talhão no mapa para calcular automaticamente.";});
$("#fieldForm").addEventListener("submit",e=>{if(e.submitter?.value==="cancel")return;e.preventDefault();const id=$("#fieldId").value;const oldField=id?fieldById(id):null;const map=maps.mainMap;const f={...(oldField||{}),id:id||"f"+Date.now(),name:$("#fieldName").value.trim(),area:Number($("#fieldArea").value),crop:$("#fieldCrop").value,soil:$("#fieldSoil").value.trim(),soilType:$("#fieldSoilType").value,ph:$("#fieldPH").value,drainage:$("#fieldDrainage").value,waterSource:$("#fieldWater").value,pestHistory:$("#fieldPests").value.trim(),fertilizer:$("#fieldFertilizer").value.trim(),date:$("#fieldDate").value,previous:oldField?.previous||"",notes:$("#fieldNotes").value.trim(),observations:oldField?.observations||[],boundary:map?._pendingBoundary||oldField?.boundary||null};if(!f.name||!f.area||f.area<=0){toast("Preencha o nome e uma área válida.");return}if(id)state.fields=state.fields.map(x=>x.id===id?f:x);else state.fields.push(f);$("#fieldDialog").close();if(map?._drawPolygon){map.removeLayer(map._drawPolygon);map._drawPolygon=null;}if(map){map._pendingBoundary=null;map._pendingArea=null;}$("#fieldAreaHelp").textContent="Introduza a área ou desenhe o talhão no mapa para calcular automaticamente.";saveState();toast(id?"Talhão actualizado.":"Talhão adicionado.")});
$("#addCampaign").addEventListener("click",()=>{$("#campaignYear").value="2026/2027";$("#campaignArea").value="";$("#campaignYield").value="";$("#campaignNotes").value="";const selectedCampaignField=fieldById($("#campaignField").value);if(selectedCampaignField){$("#campaignArea").value=selectedCampaignField.area;$("#campaignCrop").value=selectedCampaignField.crop==="Em preparação"?"Milho":selectedCampaignField.crop;}$("#campaignPlanting").value="";$("#campaignHarvest").value="";$("#campaignCost").value="";$("#campaignInputs").value="";$("#campaignIrrigation").value="";$("#campaignProblems").value="";$("#campaignDialog").showModal()});
$("#campaignField").addEventListener("change",()=>{const f=fieldById($("#campaignField").value);if(f&&(!$("#campaignArea").value||Number($("#campaignArea").value)===0))$("#campaignArea").value=f.area});
$("#campaignForm").addEventListener("submit",e=>{if(e.submitter?.value==="cancel")return;e.preventDefault();const f=fieldById($("#campaignField").value);if(!f){toast("Adicione primeiro um talhão.");return}const c={id:"c"+Date.now(),year:$("#campaignYear").value.trim(),fieldId:f.id,crop:$("#campaignCrop").value,area:Number($("#campaignArea").value),yield:Number($("#campaignYield").value)||0,plantingDate:$("#campaignPlanting").value,harvestDate:$("#campaignHarvest").value,cost:Number($("#campaignCost").value)||0,inputs:$("#campaignInputs").value.trim(),irrigation:$("#campaignIrrigation").value.trim(),problems:$("#campaignProblems").value.trim(),notes:$("#campaignNotes").value.trim()};if(!c.year||!c.area||c.area<=0){toast("Indique campanha e área válida.");return}state.campaigns.unshift(c);f.previous=f.crop;f.crop=c.crop;f.date=c.plantingDate||f.date;f.notes=c.notes||f.notes;$("#campaignDialog").close();saveState();toast("Campanha registada no passaporte do talhão.")});

function createFarmPolygons(map){
  const center=[Number(state.settings.lat),Number(state.settings.lon)];
  const demoShapes=[[[.006,-.012],[.006,-.004],[-.001,-.004],[-.001,-.012]],[[.006,.001],[.006,.009],[-.001,.009],[-.001,.001]],[[-.003,-.012],[-.003,-.004],[-.010,-.004],[-.010,-.012]],[[-.003,.001],[-.003,.009],[-.010,.009],[-.010,.001]],[[-.012,-.012],[-.012,-.004],[-.019,-.004],[-.019,-.012]],[[-.012,.001],[-.012,.009],[-.019,.009],[-.019,.001]]];
  return state.fields.map((f,i)=>{
    const coords=Array.isArray(f.boundary)&&f.boundary.length>=3?f.boundary:demoShapes[i%demoShapes.length].map(([a,b])=>[center[0]+a,center[1]+b]);
    const color=f.crop==="Milho"?"#d7a93d":f.crop==="Feijão"?"#42865b":f.crop==="Soja"?"#7185b4":"#9aa59c";
    const p=L.polygon(coords,{color,weight:2,fillColor:color,fillOpacity:.28}).addTo(map);
    p.bindTooltip(`${f.name} · ${f.crop}${f.boundary?` · ${Number(f.area).toFixed(2)} ha`:" · limite ilustrativo"}`);
    p.on("click",()=>selectField(f.id));p._fieldId=f.id;return p;
  });
}
function polygonAreaHa(points){
  if(!points||points.length<3)return 0;
  const R=6378137, lat0=points.reduce((a,p)=>a+p[0],0)/points.length*Math.PI/180;
  const xy=points.map(([lat,lon])=>[R*lon*Math.PI/180*Math.cos(lat0),R*lat*Math.PI/180]);
  let area=0;for(let i=0,j=xy.length-1;i<xy.length;j=i++)area+=xy[j][0]*xy[i][1]-xy[i][0]*xy[j][1];
  return Math.abs(area/2)/10000;
}
function updateDrawingPreview(map){
  const pts=map._drawPoints||[];if(map._drawLine)map.removeLayer(map._drawLine);if(map._drawMarkers)map._drawMarkers.forEach(x=>map.removeLayer(x));
  map._drawMarkers=pts.map((pt,i)=>L.circleMarker(pt,{radius:5,color:"#fff",weight:2,fillColor:"#1f704b",fillOpacity:1}).addTo(map).bindTooltip(`Ponto ${i+1}`));
  if(pts.length>=2)map._drawLine=L.polyline(pts,{color:"#1f9b63",weight:3,dashArray:"7 6"}).addTo(map);
  const area=polygonAreaHa(pts);$("#drawArea").textContent=pts.length>=3?`Área estimada: ${area.toFixed(3)} ha`:`Área calculada: ${pts.length}/3 pontos mínimos`;
}
function startFieldDrawing(){
  const map=maps.mainMap;if(!map)return;cancelFieldDrawing();map._drawingField=true;map._drawPoints=[];map.doubleClickZoom.disable();
  $("#drawToolbar").hidden=false;$("#drawStatus").textContent="A desenhar novo talhão";$("#addFieldMap").textContent="A desenhar…";
  toast("Clique nos cantos do terreno. Depois seleccione Concluir desenho.");
}
