function applyEarthObservationLayer(showToast=true){const el=$("#satellitePreview"),m=el?._map;if(!m){$("#earthLayerStatus").textContent="O mapa ainda não está pronto. Abra novamente a página Monitorização.";return}const layerId=$("#earthLayerSelect")?.value||"MODIS_Terra_NDVI_8Day";const def=EARTH_LAYERS[layerId];if(!def){$("#earthLayerStatus").textContent="Produto NASA não reconhecido.";return}const date=$("#earthObservationDate")?.value||defaultEarthDate(layerId);if(!date){$("#earthLayerStatus").textContent="Escolha uma data válida.";return}updateEarthLayerInfo(layerId);if(m._nasaOverlay){m.removeLayer(m._nasaOverlay);m._nasaOverlay=null;}const status=$("#earthLayerStatus");status.textContent=`A contactar ${def.source} para ${date}…`;let successfulTiles=0,failedTiles=0,finished=false;const overlay=L.tileLayer.wms(NASA_GIBS_WMS,{layers:layerId,styles:"",format:"image/png",transparent:true,version:"1.1.1",time:date,opacity:.82,attribution:"NASA GIBS / "+def.source});overlay.on("tileload",()=>{successfulTiles++});overlay.on("tileerror",()=>{failedTiles++});overlay.on("load",()=>{finished=true;if(successfulTiles>0){status.textContent=`Camada NASA carregada: ${def.title}. Data: ${date}. Tiles recebidos: ${successfulTiles}${failedTiles?` · falhas: ${failedTiles}`:""}.`; }else{status.textContent=`O serviço respondeu, mas não enviou imagens para ${date}. Escolha outra data.`;}});m._nasaOverlay=overlay;overlay.addTo(m);setTimeout(()=>{if(!finished&&m.hasLayer(overlay)){status.textContent=successfulTiles>0?`Recebidos ${successfulTiles} mosaicos; ainda há pedidos pendentes. Falhas: ${failedTiles}.`:`Não chegaram imagens da NASA após 15 segundos. Verifique a ligação, a data e a disponibilidade do produto.`}},15000);if(showToast)toast("Pedido enviado. A aguardar confirmação dos mosaicos NASA…")}
