function updateSimulatorContext(){const f=fieldById($("#simField").value);if(!f){$("#simFieldContext").textContent="Adicione um talhão para começar.";return}const history=state.campaigns.filter(c=>c.fieldId===f.id).sort((a,b)=>(a.plantingDate||a.year).localeCompare(b.plantingDate||b.year));const last=history.at(-1);$("#simFieldContext").innerHTML=`<b>Perfil carregado: ${esc(f.name)}</b><span>Cultura actual: ${esc(f.crop)} · Anterior: ${esc(last?.crop||f.previous||"Não registada")}</span><span>Solo: ${esc(f.soil||"Não caracterizado")} · pH: ${esc(f.ph||"não medido")}</span><span>Campanhas no histórico: ${history.length}</span>${weatherData&&weatherData.fieldId===f.id?`<span>Clima recente: ${weatherData.keys.slice(-7).reduce((a,k)=>a+Math.max(0,Number(weatherData.precipitation?.[k])||0),0).toFixed(1)} mm de chuva nos últimos 7 dias; humidade superficial SMAP ${Number.isFinite(weatherData.smapSurface)?weatherData.smapSurface.toFixed(3)+" m³/m³":"ainda indisponível"}.</span>`:`<span>Dados climáticos deste talhão ainda não foram carregados na Monitorização.</span>`}` }
function runSimulation(){const f=fieldById($("#simField").value);if(!f){toast("Seleccione um talhão.");return}const history=state.campaigns.filter(c=>c.fieldId===f.id).sort((a,b)=>(a.plantingDate||a.year).localeCompare(b.plantingDate||b.year));const lastCrop=history.at(-1)?.crop||f.crop;const soilChoice=$("#soilType").value;const soil=soilChoice==="auto"?(f.soilType||"unknown"):soilChoice;const waterChoice=$("#waterLevel").value;const water=waterChoice==="auto"?(f.waterSource==="Chuva"?"medium":f.waterSource==="Não registada"?"unknown":"high"):waterChoice;const chosen=$$(".strategy-check:checked").map(x=>x.value);if(!chosen.length){toast("Seleccione pelo menos uma estratégia.");return}const cereal=["Milho","Arroz"].includes(lastCrop)?lastCrop:"Milho";const legume=["Feijão","Soja"].includes(lastCrop)?(lastCrop==="Feijão"?"Soja":"Feijão"):"Feijão";const configs={A:{title:`${lastCrop} → ${lastCrop} → ${lastCrop}`,sequence:`${lastCrop} → ${lastCrop} → ${lastCrop}`,pros:"Continuidade operacional e aproveitamento do conhecimento da cultura.",risks:"A repetição pode favorecer a acumulação de pragas e doenças específicas e aumentar a pressão sobre nutrientes. Requer monitorização e plano de fertilidade."},B:{title:`${lastCrop} → ${legume} → ${cereal}`,sequence:`${lastCrop} → ${legume} → ${cereal}`,pros:"A alternância com uma leguminosa pode diversificar o sistema e contribuir para a dinâmica do azoto, dependendo da espécie e do maneio.",risks:"É necessário confirmar adaptação da variedade, calendário de chuvas, mercado e pressão de pragas."},C:{title:`${legume} → ${cereal} → Cobertura vegetal`,sequence:`${legume} → ${cereal} → Cultura de cobertura`,pros:"Combina grupos de culturas diferentes e pode manter o solo coberto entre campanhas.",risks:"A cultura de cobertura precisa de espécie adequada, semente e água suficiente para estabelecimento."}};const soilText={sandy:"Solo arenoso: verificar retenção de água e matéria orgânica.",loamy:"Solo franco: confirmar estrutura, fertilidade e drenagem.",clayey:"Solo argiloso: avaliar drenagem, compactação e janela de trabalho.",unknown:"Textura desconhecida: fazer análise ou caracterização antes de decidir."}[soil]||"Caracterizar o solo antes da decisão.";const ph=Number(f.ph);const phText=f.ph?(ph<5.5?`pH ${f.ph}: pode haver limitações de acidez a avaliar.`:ph>7.5?`pH ${f.ph}: avaliar disponibilidade de nutrientes em solo alcalino.`:`pH ${f.ph}: interpretar em conjunto com análise de nutrientes.`):"pH não registado: recomenda-se análise do solo.";const waterText={low:"Água limitada: confirmar duração do ciclo e risco de défice hídrico.",medium:"Água baseada sobretudo em chuva: alinhar a época de sementeira com o início regular das chuvas.",high:"Fonte de água registada: confirmar caudal, custo e disponibilidade durante o ciclo.",unknown:"Disponibilidade de água não caracterizada: confirmar antes de seleccionar a cultura."}[water]||"Disponibilidade de água não caracterizada.";const results=chosen.map(k=>{const c=configs[k];const alerts=[];if(soil==="unknown")alerts.push("solo por caracterizar");if(water==="unknown")alerts.push("água por caracterizar");if(history.length<2)alerts.push("histórico curto");if(k==="A")alerts.push("atenção à repetição da cultura");return `<div class="strategy-result"><h3>Estratégia ${k} · ${esc(c.sequence)}</h3><p><b>Possíveis vantagens:</b> ${esc(c.pros)}</p><p><b>Riscos / limitações:</b> ${esc(c.risks)}</p><p><b>Pontos específicos deste talhão:</b> ${esc(soilText)} ${esc(phText)} ${esc(waterText)}</p><p><b>Antes de escolher:</b> ${esc(alerts.join("; ")||"validar variedade, calendário e análise de solo")}.</p></div>`}).join("");$("#simResults").innerHTML=`<div class="eyebrow">COMPARAÇÃO DE CENÁRIOS</div><h2 style="margin-top:7px">Análise para ${esc(f.name)}</h2><p class="panel-sub">Baseada no perfil e nos registos disponíveis. Não é previsão de produtividade.</p>${results}${weatherData&&weatherData.fieldId===f.id?`<div class="callout">Contexto ambiental consultado: ${weatherData.keys.slice(-7).reduce((a,k)=>a+Math.max(0,Number(weatherData.precipitation?.[k])||0),0).toFixed(1)} mm de precipitação nos últimos 7 dias disponíveis; humidade superficial SMAP ${Number.isFinite(weatherData.smapSurface)?weatherData.smapSurface.toFixed(3)+" m³/m³":"indisponível"}. Estes dados são regionais e devem ser confirmados no terreno.</div>`:`<div class="callout">Ainda não existem dados climáticos carregados para este talhão. Abra Monitorização e actualize os dados antes de usar o contexto climático na comparação.</div>`}<div class="callout warning-callout">Esta análise usa regras agronómicas gerais e não está calibrada para a parcela. Não inventa rendimento nem garante sucesso. Antes de plantar, confirme rotação, variedades, época, fertilidade, pragas e água com um técnico agrícola local.</div>`}
$("#simField").addEventListener("change",updateSimulatorContext);

$("#runSimulation").addEventListener("click",runSimulation);
function renderLatestObservation(){const f=fieldById(monitoringFieldId);if(!f)return;const last=(f.observations||[]).at(-1);$("#latestObservation").textContent=last?`Último registo (${last.date}): humidade ${last.moisture||"não avaliada"}; estado da cultura ${last.cropState||"não avaliado"}. ${last.notes||""}`:"Ainda não existem observações registadas para este talhão."}
$("#fieldObservationForm").addEventListener("submit",e=>{e.preventDefault();const f=fieldById(monitoringFieldId);if(!f){toast("Seleccione um talhão.");return}f.observations=f.observations||[];f.observations.push({date:new Date().toLocaleDateString("pt-PT"),moisture:$("#observedMoisture").value,cropState:$("#observedCropState").value,notes:$("#observedNotes").value.trim()});$("#observedMoisture").value="";$("#observedCropState").value="";$("#observedNotes").value="";saveState();renderLatestObservation();renderFieldAnalysis();toast("Observação guardada no passaporte do talhão.")});
function assistantAnswer(q){const s=q.toLowerCase();if(s.includes("cultura")||s.includes("plant"))return `Actualmente existem ${state.fields.length} talhões registados. ${state.fields.map(f=>`${f.name}: ${f.crop}`).join("; ")}. Estes dados vêm dos registos locais da demonstração.`;if(s.includes("produção")||s.includes("colheita")||s.includes("talhão a")){const f=state.fields.find(x=>s.includes(x.name.toLowerCase()))||state.fields[0];const cs=state.campaigns.filter(c=>c.fieldId===f?.id);return f?`${f.name} tem ${f.area} hectares e a cultura actual registada é ${f.crop}. ${cs.length?`Há ${cs.length} campanhas no histórico, com produção total registada de ${cs.reduce((a,c)=>a+Number(c.yield||0),0).toFixed(1)} toneladas.`:"Ainda não há campanhas associadas."}`:"Não encontrei esse talhão."}if(s.includes("rotação"))return "A rotação consiste em alternar culturas ao longo das campanhas. Pode ajudar a diversificar o sistema e interromper ciclos de algumas pragas e doenças. A escolha depende do clima, solo, água, mercado e espécies utilizadas. Consulte um agrónomo para validar a sequência.";if(s.includes("chuva")||s.includes("clima")||s.includes("tempo"))return weatherData?`O último registo consultado na NASA POWER é de ${weatherData.last}. Temperatura média: ${weatherData.temperature[weatherData.last]} °C; precipitação: ${weatherData.precipitation[weatherData.last]} mm. São dados em grelha para a região, não uma medição dentro do talhão.`:"Ainda não há dados meteorológicos carregados. Abra Monitorização e tente actualizar a NASA POWER.";return "Posso consultar os talhões, culturas, área e campanhas que estão guardados neste navegador. Para responder com rigor sobre pragas, fertilização ou doenças, é necessária informação local e validação de um técnico agrícola. Experimente perguntar por um talhão ou por uma campanha."}
function addMessage(text,who){const el=document.createElement("div");el.className="chat-bubble "+who;el.textContent=text;$("#chatMessages").append(el);$("#chatMessages").scrollTop=$("#chatMessages").scrollHeight}
$("#chatForm").addEventListener("submit",e=>{e.preventDefault();const q=$("#chatInput").value.trim();if(!q)return;addMessage(q,"user");$("#chatInput").value="";setTimeout(()=>addMessage(assistantAnswer(q),"bot"),250)});$$(".suggestion").forEach(b=>b.addEventListener("click",()=>{$("#chatInput").value=b.textContent;$("#chatForm").requestSubmit()}));
